// Service worker, generated by scripts/stamp-build.mjs from scripts/sw.template.js.
// Network first for everything (a stale build is worse than a slow load), with
// the cache as the fallback so the page opens offline; the whole build is
// precached on install and old caches are dropped on activate. Cross-origin
// requests (nodes, Esplora, relays, price API) are never cached.
const BUILD = '20261003T061058-89cda95';
const CACHE = 'btc-alph-swap-' + BUILD;
const ASSETS = [
  "./contracts/atomic-swap.json",
  "./icons/alephium.png",
  "./icons/bitcoin.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/icon.svg",
  "./index.html",
  "./js/adaptor.js",
  "./js/alph-verify.js",
  "./js/alph.js",
  "./js/app.js",
  "./js/bip327-selftest.js",
  "./js/btc.js",
  "./js/build.js",
  "./js/config.js",
  "./js/curve.js",
  "./js/keys.js",
  "./js/modal.js",
  "./js/musig2.js",
  "./js/nip44.js",
  "./js/petri-net.js",
  "./js/petri-viewer.js",
  "./js/qrscan.js",
  "./js/swap-engine.js",
  "./js/taproot-utils.js",
  "./js/timelocks.js",
  "./manifest.webmanifest",
  "./spec/bip327/det_sign_vectors.json",
  "./spec/bip327/key_agg_vectors.json",
  "./spec/bip327/nonce_agg_vectors.json",
  "./spec/bip327/nonce_gen_vectors.json",
  "./spec/bip327/sig_agg_vectors.json",
  "./spec/bip327/sign_verify_vectors.json",
  "./spec/bip327/tweak_vectors.json",
  "./vendor/SHA256SUMS",
  "./vendor/alephium-web3.js",
  "./vendor/bech32.js",
  "./vendor/bitcoinjs-lib.js",
  "./vendor/buffer.js",
  "./vendor/jsqr.js",
  "./vendor/noble-ciphers-chacha.js",
  "./vendor/noble-curves-secp256k1.js",
  "./vendor/noble-curves-utils.js",
  "./vendor/noble-hashes-hkdf.js",
  "./vendor/noble-hashes-hmac.js",
  "./vendor/noble-hashes-sha256.js",
  "./vendor/noble-hashes-utils.js",
  "./vendor/qrcode-generator.js",
  "./vendor/scure-bip32.js",
  "./vendor/scure-bip39-english.js",
  "./vendor/scure-bip39.js",
  "./vendor/tiny-secp256k1.js",
  "./version.json"
];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'GET' || url.origin !== self.location.origin) return;
  event.respondWith(
    fetch(event.request).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(event.request, copy)); }
      return res;
    }).catch(() => caches.match(event.request, { ignoreSearch: true }).then((hit) => hit || (url.pathname.endsWith('/') || url.pathname.endsWith('.html') ? caches.match('./index.html') : undefined)))
  );
});
